func adminUserStatusTone(status string) adminTone {
	switch status {
	case "active":
		return adminToneSuccess
	case "pending":
		return adminToneWarning
	case "disabled":
		return adminToneDanger
	}
	return adminToneNeutral
}

func adminUserRoleTone(role string) adminTone {
	switch role {
	case "management_admin":
		return adminToneInfo
	case "management_user":
		return adminToneNeutral
	}
	return adminTonePlain
}

func adminUserMFATone(label string) adminTone {
	if label == "required" {
		return adminToneInfo
	}
	return adminToneNeutral
}

func adminUserInvitationTone(state string) adminTone {
	switch state {
	case "active":
		return adminToneSuccess
	case "expired":
		return adminToneWarning
	case "revoked":
		return adminToneDanger
	}
	return adminToneNeutral
}

